6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Rejects creating an owner when the owner's city already contains 50 or more existing
10	 * owners. Cities are compared case-insensitively on their trimmed value. Runs before
11	 * {@link SaveOwner}, so the owner being created is not counted. A city at (or over)
12	 * capacity escalates as a 409 via {@link CityAtCapacityException}.
13	 */
14	public class RejectCityAtCapacity {
15	
16	    private static final int CITY_CAPACITY = 50;
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        String city = owner.getCity() == null ? "" : owner.getCity().trim();
21	        long count = ownerRepository.findAll().stream()
22	                .filter(existing -> existing.getCity() != null
