3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * The identity of a household: the same last name and the same address. The last name is
10	 * compared case-insensitively with whitespace trimmed and collapsed; the address is compared
11	 * in its normalized form (see {@link OwnerAddresses#normalize}), so e.g. "7  elm  ave" matches
12	 * "7 ELM AVENUE".
13	 *
14	 * <p>Single-sources the "what is a household" definition used by {@link AssignHousehold} to
15	 * decide who shares a {@code householdId}; that shared id then feeds the owner's
16	 * {@code identityKey} (see {@link OwnerIdentity}), which is what duplicate detection rejects on.
17	 */
18	final class HouseholdKey {
19	
20	    private final String lastName;
21	
22	    private final String address;
23	
24	    private HouseholdKey(String lastName, String address) {
25	        this.lastName = lastName;
26	        this.address = address;
27	    }
28	
29	    /** The household the given owner belongs to. */
30	    static HouseholdKey of(Owner owner) {
31	        return new HouseholdKey(normalize(owner.getLastName()), OwnerAddresses.normalize(owner.getAddress()));
32	    }
33	
34	    /** Whether {@code owner} belongs to this household. */
35	    boolean matches(Owner owner) {
36	        return equals(of(owner));
37	    }
38	
39	    /** Stable canonical form of the key, suitable for deriving a shared identifier. */
40	    String canonical() {
41	        return lastName + "|" + address;
42	    }
43	
44	    @Override
45	    public boolean equals(Object o) {
46	        if (this == o) {
47	            return true;
48	        }
49	        if (!(o instanceof HouseholdKey other)) {
50	            return false;
51	        }
52	        return lastName.equals(other.lastName) && address.equals(other.address);
53	    }
54	
55	    @Override
56	    public int hashCode() {
57	        return Objects.hash(lastName, address);
58	    }
59	
60	    @Override
61	    public String toString() {
62	        return canonical();
63	    }
64	
65	    /** Lower-case, trim, and collapse any run of whitespace to a single space. */
66	    private static String normalize(String value) {
67	        if (value == null) {
68	            return "";
69	        }
70	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
71	    }
72	}
